import { readFileSync } from "node:fs";
import { describe, expect, it } from "vitest";
import {
  DEBUG_MANIFEST,
  DEBUG_MANIFEST_SOURCE,
  drift,
  MAIN_MANIFEST,
  missingPermissions,
  planManifest,
  REQUIRED_PERMISSIONS,
} from "../../tools/android-setup.mjs";

// `android/` is generated by `cap add`, so a hand-edit inside it is a claim that dies the first
// time the folder is deleted. tools/android-setup.mjs holds the claim; this test holds the tool
// honest against the tree on disk, which is what makes "delete android/, bun tools/android-setup"
// a real instruction rather than a hope.

/** The manifest a bare `cap add android` writes: INTERNET only, no debug overlay. */
const TEMPLATE_MANIFEST = `<?xml version="1.0" encoding="utf-8"?>
<manifest xmlns:android="http://schemas.android.com/apk/res/android">
    <application android:allowBackup="true" />
    <!-- Permissions -->
    <uses-permission android:name="android.permission.INTERNET" />
</manifest>
`;

describe("android-setup", () => {
  it("adds every runtime permission the plugin layer cannot declare for us", () => {
    const patched = planManifest(TEMPLATE_MANIFEST);
    for (const name of REQUIRED_PERMISSIONS) {
      expect(missingPermissions(patched), name).toEqual([]);
      expect(patched).toContain(`<uses-permission android:name="${name}" />`);
    }
    // The template's own line survives: the tool appends, it never rewrites what is there.
    expect(patched.match(/android.permission.INTERNET/g)).toHaveLength(1);
  });

  it("is idempotent, so a second run changes nothing", () => {
    const once = planManifest(TEMPLATE_MANIFEST);
    expect(planManifest(once)).toBe(once);
  });

  it("keeps the location pair, without which the prompt can never appear", () => {
    expect(REQUIRED_PERMISSIONS).toContain("android.permission.ACCESS_FINE_LOCATION");
    expect(REQUIRED_PERMISSIONS).toContain("android.permission.ACCESS_COARSE_LOCATION");
  });

  it("matches the tree on disk — the committed android/ is what the tool reproduces", () => {
    expect(drift(), `run: bun tools/android-setup.mjs`).toEqual([]);
    expect(readFileSync(MAIN_MANIFEST, "utf8")).toContain("</manifest>");
    expect(readFileSync(DEBUG_MANIFEST, "utf8")).toBe(DEBUG_MANIFEST_SOURCE);
  });
});
